-- Shared-cab extra setup for LOCAL testing: the data the shared-cab flows need on top of the seeded dev stack. LOCAL ONLY, never a
-- shared environment: the Shillong shared-cab feed is hosted on the imported Chennai NAMMA_YATRI city, so the ids below are the
-- local seed's (rider city c7e3c3eb-…, driver city f8e9db0a-…) and the geometry is labelled Chennai. Run by hand, in order:
--   psql -h localhost -p 5434 -U atlas_superuser -d atlas_dev -f Backend/dev/local-testing-data/shared-cab-extra-setup.sql
-- then clear the apps' Redis config caches and restart the processes. Idempotent.
-- Schema is not here: columns come from the storage YAML (migrations-read-only), the partial indexes from
-- ddl-migrations/rider-app/1586-shared-cab-partial-indexes.sql, and the push templates from
-- feature-migrations/0083-shared-cab-notification-templates.sql.

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- 1. Feed config: integrated_bpp_config rows for the shared-cab agency (rider MULTIMODAL + APPLICATION, driver APPLICATION)
--    and the OTP endpoints pointed at the local GTFS servers.
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- LOCAL e2e seed: Shillong shared-cab feed hosted on the (imported) Chennai NAMMA_YATRI city.
-- rider side
UPDATE atlas_app.merchant_service_config SET config_json = jsonb_set(config_json::jsonb,'{baseUrl}','"http://localhost:8089/otp/gtfs/v1/"')::json
 WHERE service_name='MultiModal_OTPTransit' AND merchant_operating_city_id='c7e3c3eb-cc15-46d4-ba04-5af55ac87874';
UPDATE atlas_app.merchant_service_config SET config_json = jsonb_set(config_json::jsonb,'{baseUrl}','"http://localhost:8090"')::json
 WHERE service_name='MultiModalStaticData_OTPTransit' AND merchant_operating_city_id='c7e3c3eb-cc15-46d4-ba04-5af55ac87874';

SELECT md5('e2e-shared-cab-ibc')::uuid::text, 'shillong_shared_cab', 'FRFS', 'shillong_shared_cab', '4b17bd06-ae7e-48e9-85bf-282fb310209c', 'c7e3c3eb-cc15-46d4-ba04-5af55ac87874', 'MULTIMODAL', config_json, 'BUS', now(), now()
FROM atlas_app.integrated_bpp_config WHERE id='b76b3f68-1581-4fe2-9c56-b8968212c95d'
ON CONFLICT DO NOTHING;

-- The cab feed replaces the imported Chennai BUS row on this city: GIMS serves only the cab feed, so a second MULTIMODAL BUS
-- row 404s every bus-path lookup (routeServiceability takes the first row).
DELETE FROM atlas_app.integrated_bpp_config WHERE id='b76b3f68-1581-4fe2-9c56-b8968212c95d' AND EXISTS (SELECT 1 FROM atlas_app.integrated_bpp_config WHERE id=md5('e2e-shared-cab-ibc')::uuid::text);

-- driver side
SELECT md5('e2e-shared-cab-ibc')::uuid::text, 'shillong_shared_cab', 'FRFS', 'shillong_shared_cab', '7f7896dd-787e-4a0b-8675-e9e6fe93bb8f', 'f8e9db0a-96c8-49e4-942a-3e3f7265d2da', 'APPLICATION', config_json, 'SHARED_CAB', 'Chennai', now(), now()
FROM atlas_driver_offer_bpp.integrated_bpp_config WHERE agency_key='chennai_bus' LIMIT 1
ON CONFLICT DO NOTHING;
UPDATE atlas_app.integrated_bpp_config SET agency_key='shillong_shared_cab:SHARED_CAB' WHERE id=md5('e2e-shared-cab-ibc')::uuid::text; UPDATE atlas_driver_offer_bpp.integrated_bpp_config SET agency_key='shillong_shared_cab:SHARED_CAB' WHERE id=md5('e2e-shared-cab-ibc')::uuid::text; -- R62: agency_key must match across DBs

-- The cab answer of /v2/multimodal/routeServiceability look for a BUS + APPLICATION config for the shared-cab
-- agency: a second rider row.
SELECT md5('e2e-shared-cab-ibc-app')::uuid::text, agency_key, domain, feed_key, merchant_id, merchant_operating_city_id, 'APPLICATION', config_json, vehicle_category, now(), now()
FROM atlas_app.integrated_bpp_config WHERE id = md5('e2e-shared-cab-ibc')::uuid::text
ON CONFLICT DO NOTHING;

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- 2. Geometry: a city polygon around Shillong so its coordinates resolve to the test city.
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- The apps read geom_geo_json (in-memory cached); the LTS needs Backend/geo_config/<name>.json separately (see README).
SELECT md5('e2e-shillong-geom-app')::uuid::text, 'Chennai', 'Chennai', 'TamilNadu', ST_SetSRID(ST_MakeEnvelope(91.80,25.49,92.02,25.69),0)
WHERE NOT EXISTS (SELECT 1 FROM atlas_app.geometry WHERE id=md5('e2e-shillong-geom-app')::uuid::text);
SELECT md5('e2e-shillong-geom-drv')::uuid::text, 'Chennai', 'Chennai', 'TamilNadu', ST_SetSRID(ST_MakeEnvelope(91.80,25.49,92.02,25.69),0)
WHERE NOT EXISTS (SELECT 1 FROM atlas_driver_offer_bpp.geometry WHERE id=md5('e2e-shillong-geom-drv')::uuid::text);
UPDATE atlas_app.geometry SET geom_geo_json='{"type":"MultiPolygon","coordinates":[[[[91.80,25.49],[92.02,25.49],[92.02,25.69],[91.80,25.69],[91.80,25.49]]]]}' WHERE id=md5('e2e-shillong-geom-app')::uuid::text; -- apps use geom_geo_json (in-mem cached), not geom

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- 3. Fares: the SHARED_CAB service tier, a fare policy and route fare product per route, and the per-stop-pair seat fares.
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- Shared-cab fares for the ops-sheet Shillong feed: the SHARED_CAB tier plus the fare policy, route fare product and per-pair seat fares
-- of the routes the hurl suite drives (route_a SC-R1-F / route_a_return SC-R1-R / route_b SC-R2-R). Rows are the subset of the ops feed's
-- generated fares for those routes, and idempotent: the policies' stop fares are cleared first.
VALUES ('SHARED_CAB','Shared cab',md5('e2e-sc-tier')::uuid::text,'a9f70a47-6bf9-6c26-f04e-d2a21c3628b5','Shared Cab','4b17bd06-ae7e-48e9-85bf-282fb310209c','c7e3c3eb-cc15-46d4-ba04-5af55ac87874','SHARED_CAB','Shared Cab',now(),now(),false,true) ON CONFLICT DO NOTHING;
DELETE FROM atlas_app.route_stop_fare WHERE fare_policy_id IN (md5('e2e-ops-fp-SC-R1-F')::uuid::text,md5('e2e-ops-fp-SC-R1-R')::uuid::text,md5('e2e-ops-fp-SC-R2-R')::uuid::text);

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- 4. Switch shared cab on for the test city. frfs_ticket_booking (and driver-app's vehicle_trip) stay on KV, as in prod: the flows' Postgres
--    reads retry for the drainer's lag, so the rider drainer must run (THREAD_PER_POD_COUNT above 1 keeps that lag to a few seconds).
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- shared cab on for the test city (NULL would follow the SHARED_CAB IntegratedBPPConfig alone, false turns it off)
UPDATE atlas_app.rider_config SET shared_cab_config = '{"enabled":true,"callEnabled":true,"chatEnabled":true}' WHERE merchant_operating_city_id = 'c7e3c3eb-cc15-46d4-ba04-5af55ac87874';
-- optional, for the finding-timeout scenario: 25 s instead of 20 min
-- UPDATE atlas_app.rider_config SET shared_cab_config = (COALESCE(shared_cab_config::jsonb, '{}') || '{"findingTimeoutSec":25}')::json WHERE merchant_operating_city_id = 'c7e3c3eb-cc15-46d4-ba04-5af55ac87874';
